sys_script_include.script:
var HoldingPortal = Class.create();
HoldingPortal.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    createRequestBodyForRemoteTableAPICall: function(generatedQuery, v_table, siteCode) {
        try {
            var requestBody = {};
            var query = generatedQuery.split('^');
            var inputText;
            for (var i = 0; i < query.length; i++) {

                inputText = query[i].match(/(?:STARTSWITH|CONTAINS)([a-zA-Z0-9-]*)/);

                if (inputText && inputText[1].length >= 3) {
                    //if there is security id
                    if (query[i].indexOf('security_id') > -1 || query[i].indexOf('security_name') > -1 || query[i].indexOf('isin') > -1 || query[i].indexOf('local_market_code') > -1) {
                        if (query[i].indexOf('security_id') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.instrumentAlternateGhssIdentifier = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.instrumentAlternateGhssIdentifier = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('security_name') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.instrumentShortName = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.instrumentShortName = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('isin') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.isin = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.isin = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('local_market_code') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.instrumentAlternateIdentifierLocalSecurityCode = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.instrumentAlternateIdentifierLocalSecurityCode = '*' + inputText[1].toUpperCase() + '*';
                            }
                        }
                    } else if (query[i].indexOf('switch_account') > -1 || query[i].indexOf('switch_account_name') > -1) {
                        if (query[i].indexOf('switch_account_name') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.safekeepingAccountShortName = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.safekeepingAccountShortName = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('switch_account') > -1) {
                            if (inputText && inputText[1].length >= 4) {
                                if (query[i].indexOf('STARTSWITH') > -1) {
                                    requestBody.safekeepingAccountIdentification = inputText[1].toUpperCase() + '*';
                                } else if (query[i].indexOf('CONTAINS') > -1) {
                                    requestBody.safekeepingAccountIdentification = '*' + inputText[1].toUpperCase() + '*';
                                }
                            } else {
                                return false;
                            }
                        }
                    }
                }
            }
            var x = null;
            if (JSON.stringify(requestBody) != '{}') {
                requestBody.siteCode = siteCode;
                x = this.callRemoteTableAPI(JSON.stringify(requestBody), v_table);
            }
            return x;
        } catch (error) {
            gs.info('====================Unexpected Error in HoldingPortal - createRequestBodyForRemoteTableAPICall : ' + error.message);
        }
    },

    callRemoteTableAPI: function(requestBody, v_table) {
        try {
            var requestbody = JSON.parse(requestBody);
            var mssRemoteTableOnDemandenv;
            var mssRemoteTableOnDemandToken = gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_token');
            var response;
            var responseBody;
            var responseObj;
            var endSleep;

            var request = new sn_ws.RESTMessageV2('MSS Remote Ondemand API Send Portal', 'Get RemoteTable Data Portal');
            request.setStringParameterNoEscape('mssRemoteTableOnDemandToken', mssRemoteTableOnDemandToken);
            request.setQueryParameter('siteCode', requestbody.siteCode);

            if ('instrumentAlternateGhssIdentifier' in requestbody || 'instrumentShortName' in requestbody || 'isin' in requestbody || 'instrumentAlternateIdentifierLocalSecurityCode' in requestbody) {
                mssRemoteTableOnDemandenv = gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'instruments';
                request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', mssRemoteTableOnDemandenv);
                request.setQueryParameter('instrumentAlternateGhssIdentifier', requestbody['instrumentAlternateGhssIdentifier'] ? requestbody['instrumentAlternateGhssIdentifier'] : '');
                request.setQueryParameter('instrumentShortName', requestbody['instrumentShortName'] ? requestbody['instrumentShortName'] : '');
                request.setQueryParameter('isin', requestbody['isin'] ? requestbody['isin'] : '');
                request.setQueryParameter('instrumentAlternateIdentifierLocalSecurityCode', requestbody['instrumentAlternateIdentifierLocalSecurityCode'] ? requestbody['instrumentAlternateIdentifierLocalSecurityCode'] : '');
                response = request.execute();
                responseBody = response.getBody();
                responseObj = JSON.parse(responseBody);
                var result = [];
                if (responseObj.status == '200' && responseObj.data.length != 0) {
                    for (i = 0; i < responseObj.data.length; i++) {
                        result.push(responseObj.data[i].instrumentAlternateGhssIdentifier);
                    }
                    return result;
                } else if (responseObj.status == '200' && responseObj.data.length == 0) {
                    gs.addErrorMessage('Please enter a valid value for Security ID (SEC ID).');
                } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                    gs.addErrorMessage('Unexpected error occured');
                } else {
                    endSleep = new GlideDuration().getNumericValue() + 10000;
                    while (new GlideDuration().getNumericValue() < endSleep) {
                        //wait 
                    }
                    if (responseObj.status == '200') {
                        for (i = 0; i < responseObj.data.length; i++) {
                            v_table.addRow({
                                security_id: responseObj.data[i].instrumentAlternateGhssIdentifier,
                                security_name: responseObj.data[i].instrumentShortName,
                                isin: responseObj.data[i].isin,
                                local_market_code: responseObj.data[i].instrumentAlternateIdentifierLocalSecurityCode,
                            });
                        }
                    } else {
                        gs.addErrorMessage('No response received');
                    }
                }


            } else if ('safekeepingAccountShortName' in requestbody || 'safekeepingAccountIdentification' in requestbody) {
                mssRemoteTableOnDemandenv = gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'accounts';
                request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', mssRemoteTableOnDemandenv);
                request.setQueryParameter('safekeepingAccountIdentification', requestbody['safekeepingAccountIdentification'] ? requestbody['safekeepingAccountIdentification'] : '');
                request.setQueryParameter('safekeepingAccountShortName', requestbody['safekeepingAccountShortName'] ? requestbody['safekeepingAccountShortName'] : '');

                response = request.execute();
                responseBody = response.getBody();
                responseObj = JSON.parse(responseBody);
                var result = [];
                if (responseObj.status == '200' && responseObj.data.length != 0) {
                    for (i = 0; i < responseObj.data.length; i++) {
                        result.push(responseObj.data[i].safekeepingAccountIdentification.slice(8));
                    }
                    return result;
                } else if (responseObj.status == '200' && responseObj.data.length == 0) {
                    gs.addErrorMessage('Please enter a valid value for Securities Account');
                } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                    gs.addErrorMessage('Please enter a valid value for Securities Account');
                } else {
                    endSleep = new GlideDuration().getNumericValue() + 10000;
                    while (new GlideDuration().getNumericValue() < endSleep) {
                        //wait 
                    }
                    if (responseObj.status == '200') {
                        for (i = 0; i < responseObj.data.length; i++) {
                            v_table.addRow({
                                switch_account: responseObj.data[i].safekeepingAccountIdentification,
                                switch_account_name: responseObj.data[i].safekeepingAccountShortName
                            });
                        }
                    } else {
                        gs.addErrorMessage('No response received');
                    }
                }

            } else if ('partyAlternateGhssIdentifier' in requestbody || 'bic' in requestbody || 'partyName' in requestbody) {
                mssRemoteTableOnDemandenv = gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'counterparties';
                request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', mssRemoteTableOnDemandenv);
                request.setQueryParameter('partyAlternateGhssIdentifier', requestbody['partyAlternateGhssIdentifier'] ? requestbody['partyAlternateGhssIdentifier'] : '');
                request.setQueryParameter('bic', requestbody['bic'] ? requestbody['bic'] : '');
                request.setQueryParameter('partyName', requestbody['partyName'] ? requestbody['partyName'] : '');
                response = request.execute();
                responseBody = response.getBody();
                responseObj = JSON.parse(responseBody);
                if (responseObj.status == '200' && responseObj.data.length != 0) {
                    for (i = 0; i < responseObj.data.length; i++) {
                        v_table.addRow({
                            counterparty_code: responseObj.data[i].partyAlternateGhssIdentifier,
                            bic: responseObj.data[i].bic,
                            counterparty_name: responseObj.data[i].partyName
                        });
                    }
                } else if (responseObj.status == '200' && responseObj.data.length == 0) {
                    gs.addErrorMessage('Please enter a valid value for Counterparty Code');
                } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                    gs.addErrorMessage('Unexpected error occured');
                } else {
                    endSleep = new GlideDuration().getNumericValue() + 10000;
                    while (new GlideDuration().getNumericValue() < endSleep) {
                        // wait 
                    }
                    if (responseObj.status == '200') {
                        for (i = 0; i < responseObj.data.length; i++) {
                            v_table.addRow({
                                counterparty_code: responseObj.data[i].partyAlternateGhssIdentifier,
                                bic: responseObj.data[i].bic,
                                counterparty_name: responseObj.data[i].partyName
                            });
                        }
                    } else {
                        gs.addErrorMessage('No response received');
                    }
                }
            }

        } catch (error) {
            gs.info('Unexpected Error in  HoldingPortal- callRemoteTableAPI : ' + error.message);
        }
    },

    type: 'HoldingPortal'
});
